import JSZip from 'jszip';
import { APP_FILE, PAGES_DIRECTORY } from './projectCode';

export const buildArchiveReadme = ({ appName }) =>
  [
    `# ${appName}`,
    '',
    'Project generated by Yuild.',
    '',
    `- \`${APP_FILE}\` defines the routes between the pages with react-router-dom.`,
    `- \`src/${PAGES_DIRECTORY}/\` contains one React component and one stylesheet for each page.`,
    '- The stylesheets describe the grid layout for mobile (base), tablet (from 768 px) and desktop (from 1200 px).',
    '- The pages import the Yuild components from `src/components`: copy the `src/components` folder of Yuild into the same position of your project.',
    '',
  ].join('\n');

export const createProjectArchive = (generatedCode) => {
  const zip = new JSZip();
  Object.entries(generatedCode.files).forEach(([path, content]) => {
    zip.file(path, content);
  });
  zip.file('README.md', buildArchiveReadme(generatedCode));
  return zip;
};
